PRAGMA foreign_keys=ON;
CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,persona TEXT NOT NULL,snapshot_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE institutions(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,simulated INTEGER NOT NULL DEFAULT 1 CHECK(simulated=1));
CREATE TABLE institution_logins(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),institution_id TEXT NOT NULL REFERENCES institutions(id),username TEXT NOT NULL,password_hash TEXT NOT NULL,UNIQUE(user_id,institution_id),UNIQUE(institution_id,username));
CREATE TABLE accounts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),institution_id TEXT NOT NULL REFERENCES institutions(id),kind TEXT NOT NULL CHECK(kind IN ('checking','savings','credit_card','brokerage','ira','cd','auto_loan','mortgage')),label TEXT NOT NULL,last_four TEXT NOT NULL,opening_cents INTEGER NOT NULL,balance_cents INTEGER NOT NULL,credit_limit_cents INTEGER,apr_bps INTEGER,minimum_payment_cents INTEGER,maturity_date TEXT,UNIQUE(id,user_id));
CREATE TABLE transactions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),account_id TEXT NOT NULL,posted_date TEXT NOT NULL,merchant TEXT NOT NULL,category TEXT NOT NULL,delta_cents INTEGER NOT NULL,transfer_group TEXT,FOREIGN KEY(account_id,user_id) REFERENCES accounts(id,user_id));
CREATE INDEX tx_user_date ON transactions(user_id,posted_date);
CREATE INDEX tx_account_date ON transactions(account_id,posted_date);
CREATE INDEX tx_transfer ON transactions(user_id,transfer_group);
CREATE TABLE connections(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),institution_id TEXT NOT NULL REFERENCES institutions(id),status TEXT NOT NULL CHECK(status IN ('active','revoked')),consent_version TEXT NOT NULL,last_sync_at TEXT,idempotency_key TEXT NOT NULL,UNIQUE(user_id,idempotency_key),UNIQUE(id,user_id));
CREATE TABLE connection_accounts(connection_id TEXT NOT NULL,user_id TEXT NOT NULL,account_id TEXT NOT NULL,PRIMARY KEY(connection_id,account_id),FOREIGN KEY(connection_id,user_id) REFERENCES connections(id,user_id),FOREIGN KEY(account_id,user_id) REFERENCES accounts(id,user_id));
CREATE TABLE scheduled_items(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),account_id TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN ('income','expense')),label TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),day_of_month INTEGER NOT NULL CHECK(day_of_month BETWEEN 1 AND 28),essential INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(account_id,user_id) REFERENCES accounts(id,user_id));
CREATE TABLE subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),account_id TEXT NOT NULL,merchant TEXT NOT NULL,cadence TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),status TEXT NOT NULL DEFAULT 'candidate',usage_confirmed TEXT,preferences_json TEXT NOT NULL DEFAULT '{}',FOREIGN KEY(account_id,user_id) REFERENCES accounts(id,user_id));
CREATE TABLE goals(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,target_cents INTEGER NOT NULL CHECK(target_cents>0),saved_cents INTEGER NOT NULL DEFAULT 0,deadline TEXT NOT NULL,priority INTEGER NOT NULL CHECK(priority BETWEEN 1 AND 5));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE login_challenges(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),code_hmac TEXT NOT NULL,expires_at TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,consumed_at TEXT,last_sent_at TEXT NOT NULL,pending_binding_hash TEXT NOT NULL);
CREATE TABLE link_previews(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),institution_id TEXT NOT NULL REFERENCES institutions(id),expires_at TEXT NOT NULL,consumed_at TEXT);
CREATE TABLE runs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),intent TEXT NOT NULL,status TEXT NOT NULL,snapshot_version INTEGER NOT NULL,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,idempotency_key),UNIQUE(id,user_id));
CREATE TABLE agent_steps(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,user_id TEXT NOT NULL,agent_id TEXT NOT NULL,status TEXT NOT NULL,result_json TEXT,FOREIGN KEY(run_id,user_id) REFERENCES runs(id,user_id));
CREATE TABLE run_events(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,user_id TEXT NOT NULL,agent_id TEXT NOT NULL,type TEXT NOT NULL,message TEXT NOT NULL,at TEXT NOT NULL,FOREIGN KEY(run_id,user_id) REFERENCES runs(id,user_id));
CREATE TABLE evidence(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),run_id TEXT NOT NULL,kind TEXT NOT NULL,source_id TEXT NOT NULL,source_mode TEXT NOT NULL CHECK(source_mode IN ('live','fixture','cached')),observed_at TEXT NOT NULL,payload_json TEXT NOT NULL,FOREIGN KEY(run_id,user_id) REFERENCES runs(id,user_id));
CREATE TABLE plans(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),run_id TEXT,version INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('proposed','accepted','stale','superseded')),snapshot_version INTEGER NOT NULL,parent_plan_id TEXT,payload_json TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(run_id,user_id) REFERENCES runs(id,user_id),UNIQUE(id,user_id));
CREATE UNIQUE INDEX one_accepted_plan_per_user ON plans(user_id) WHERE status='accepted';
CREATE TABLE demo_events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,payload_json TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,idempotency_key));
CREATE TABLE subscription_actions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),subscription_id TEXT NOT NULL REFERENCES subscriptions(id),kind TEXT NOT NULL,status TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE conversations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(id,user_id));
CREATE TABLE chat_messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(conversation_id,user_id) REFERENCES conversations(id,user_id));
